pub async fn notify_all(push: &PushClient, device_tokens: &[String], msg: &Message) -> Result<()> {
    let mut failures = 0;
    for token in device_tokens {
        if let Err(e) = push.send(token, msg).await {
            tracing::warn!(%token, error = %e, "push failed");
            failures += 1;
        }
    }
    tracing::info!(sent = device_tokens.len() - failures, failures, "push fanout done");
    Ok(())
}

