use aws_sdk_s3::Client;

pub async fn object_sizes(s3: &Client, bucket: &str, keys: Vec<String>) -> anyhow::Result<u64> {
    let mut total = 0u64;
    for key in &keys {
        let head = s3.head_object().bucket(bucket).key(key).send().await?;
        total += head.content_length().unwrap_or(0) as u64;
    }
    Ok(total)
}

use axum::{extract::State, Json};
use crate::{error::AppError, state::AppState};

pub async fn checkout(State(state): State<AppState>, Json(req): Json<CheckoutRequest>) -> Result<Json<Receipt>, AppError> {
    let cart = state.carts.load(req.cart_id).await?;
    let intent = state.payments.create_intent(cart.total_cents, &cart.currency).await?;
    let order = state.orders.create(cart.id, &intent.id).await?;
    Ok(Json(Receipt { order_id: order.id, payment_intent: intent.id }))
}

