use futures::{stream, StreamExt, TryStreamExt};
use reqwest::Client;

pub async fn fetch_pages(client: &Client, urls: Vec<String>) -> anyhow::Result<Vec<String>> {
    stream::iter(urls)
        .map(|url| {
            let client = client.clone();
            async move { client.get(&url).send().await?.error_for_status()?.text().await }
        })
        .buffer_unordered(16)
        .map_err(anyhow::Error::from)
        .try_collect()
        .await
}

use sqlx::PgPool;

pub async fn transfer(pool: &PgPool, from: i64, to: i64, cents: i64) -> sqlx::Result<()> {
    let mut tx = pool.begin().await?;
    sqlx::query!("UPDATE accounts SET balance = balance - $1 WHERE id = $2", cents, from)
        .execute(&mut *tx).await?;
    sqlx::query!("UPDATE accounts SET balance = balance + $1 WHERE id = $2", cents, to)
        .execute(&mut *tx).await?;
    sqlx::query!("INSERT INTO transfers (from_id, to_id, cents) VALUES ($1, $2, $3)", from, to, cents)
        .execute(&mut *tx).await?;
    tx.commit().await
}

use std::time::Duration;

pub async fn sync_repos(gh: &GithubClient, repos: &[String]) -> anyhow::Result<()> {
    // GitHub secondary rate limits punish concurrent requests from one token;
    // keep this strictly one-at-a-time with a pause between calls.
    for repo in repos {
        let meta = gh.repo(repo).await?;
        store_repo(meta).await?;
        tokio::time::sleep(Duration::from_millis(250)).await;
    }
    Ok(())
}

pub async fn run_migrations(db: &Db) -> anyhow::Result<()> {
    // Order matters: each step assumes the schema produced by the previous one.
    db.execute(include_str!("../sql/001_users.sql")).await?;
    db.execute(include_str!("../sql/002_orders.sql")).await?;
    db.execute(include_str!("../sql/003_orders_fk.sql")).await?;
    Ok(())
}

use futures::future::join_all;

pub async fn notify_all(push: &PushClient, device_tokens: &[String], msg: &Message) -> usize {
    let results = join_all(device_tokens.iter().map(|t| push.send(t, msg))).await;
    results.iter().filter(|r| r.is_ok()).count()
}

