use futures::future::try_join_all;

pub async fn reindex(docs: &DocStore, index: &Index, ids: &[u64]) -> anyhow::Result<()> {
    for chunk in ids.chunks(100) {
        let fetched = try_join_all(chunk.iter().map(|id| docs.get(*id))).await?;
        index.bulk_upsert(&fetched).await?;
    }
    Ok(())
}

